package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.*;
import com.vandorlabs.persistence.FrameSettings;
import com.vandorlabs.neoforge.ModernHousingTags;
import net.minecraft.nbt.*;
/** Compare the immutable renderer contract against actual Source Tile and block getters. */
public final class ScreenAppearanceChecks {
 public static void main(String[] args)throws Exception{JsonObject source;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenAppearanceReference")))){source=JsonParser.parseReader(reader).getAsJsonObject();}for(int power=-1;power<=16;power++){CompoundTag projected=new CompoundTag();projected.putInt("NativeScreenPower",power);if(NativeScreenProjection.power(projected)!=(power<0||power>15?0:power))throw new AssertionError("Unbounded public power");}CompoundTag wrongType=new CompoundTag();wrongType.putByte("NativeScreenPower",(byte)15);if(NativeScreenProjection.power(wrongType)!=0)throw new AssertionError("Wrong power type accepted");int samples=0;var catalog=NativeScreenCatalog.INSTANCE;for(var entry:source.getAsJsonArray("cases")){var row=entry.getAsJsonObject();ScreenFamily family=ScreenFamily.fromId(row.get("id").getAsString());CompoundTag tag=TagParser.parseTag(row.get("saved").getAsString());NativeScreenSettings settings=NativeScreenSettings.read(tag,catalog);FrameSettings frames=FrameSettings.read(new ModernHousingTags(tag),catalog::validFrame,catalog::validFrameSurface,catalog::validMaterial);var controls=java.util.List.of(NativeScreenControls.read(tag.getCompound("RedstonePrimary"),family.standaloneControlRows(0)),NativeScreenControls.read(tag.getCompound("RedstoneSecondary"),family.standaloneControlRows(1)));var powers=row.getAsJsonArray("powers");for(int power=0;power<16;power++){var actual=NativeScreenAppearance.of(family,settings,frames,controls,power,catalog);JsonArray values=new JsonArray();values.add(actual.activationMode);values.add(actual.state);values.add(actual.sharedArtwork);values.add(actual.primaryArtwork);values.add(actual.effectiveMode);values.add(actual.animationSpeed);values.add(actual.split);values.add(actual.overrides);for(int slot=0;slot<2;slot++){values.add(actual.surface(slot));values.add(actual.playback(slot));values.add(actual.speed(slot));}values.add(actual.light);if(!values.equals(powers.get(power)))throw new AssertionError("Appearance differs "+family+" power="+power+" actual="+values+" source="+powers.get(power)+" saved="+tag);samples++;}}if(samples!=13440||!source.get("sha256").getAsString().equals("f9a6a25b10b008b6009ce9641428ad3ede3d3cdefc4d13efc7c76fefb2aa710c"))throw new AssertionError("Source appearance coverage");System.out.println("Native Screen appearance PASS actual Source getter/power samples="+samples);}
}
